INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2800, 'skeptical', '/ˈskeptɪkl/', 'adjective', '{"zh-TW":["懷疑的；持懷疑態度的"],"en":["not easily convinced; having doubts"]}', NULL, 'skeptical about / remain skeptical / highly skeptical', '[{"en":"Investors remain skeptical about the company''s recovery plan.","zh-TW":"投資者對公司的復甦計畫持懷疑態度。"},{"en":"She was skeptical of the proposal''s feasibility.","zh-TW":"她對提案的可行性持懷疑態度。"}]', '{"noun":"skepticism, skeptic","adjective":"skeptical"}', NULL, 3, 2800, NULL),
(2801, 'skepticism', '/ˈskeptɪsɪzəm/', 'noun', '{"zh-TW":["懷疑論；懷疑態度"],"en":["a doubting attitude toward claims"]}', NULL, 'healthy skepticism / meet with skepticism / express skepticism', '[{"en":"The proposal was met with skepticism from investors.","zh-TW":"該提案遭到投資者的質疑。"},{"en":"A healthy skepticism is important in business decisions.","zh-TW":"在商業決策中保持健康的懷疑態度很重要。"}]', '{"noun":"skepticism, skeptic","adjective":"skeptical"}', NULL, 4, 2801, NULL),
(2802, 'sketch', '/sketʃ/', 'noun', '{"zh-TW":["素描；草圖"],"en":["a rough drawing made quickly"]}', '{"root":{"text":"sketch","meaning":"quick drawing (速寫)"},"logic":"源自荷蘭語 schets（快速繪畫）。"}', 'pencil sketch / rough sketch', '[{"en":"She did a quick sketch of the building.","zh-TW":"她快速畫了一張建築物的草圖。"},{"en":"The designer showed us several sketches.","zh-TW":"設計師給我們看了幾張草圖。"}]', '{"verb":"sketch","adjective":"sketchy"}', NULL, 2, 2802, NULL),
(2803, 'skill', '/skɪl/', 'noun', '{"zh-TW":["技能；技巧"],"en":["the ability to do something well"]}', NULL, 'communication skills / skill set / develop skills', '[{"en":"Employees need to develop new skills regularly.","zh-TW":"員工需要定期發展新技能。"},{"en":"Strong leadership skills are essential for this role.","zh-TW":"這個職位需要很強的領導技能。"}]', '{"noun":"skill","adjective":"skilled, skillful"}', NULL, 2, 2803, 457),
(2804, 'skilled', 'skɪld', 'adjective', '{"zh-TW":["熟練的；有技能的","老練的"],"en":["having expertise","trained and proficient"]}', NULL, 'skilled worker/skilled professional', '[{"en":"We are looking for skilled engineers.","zh-TW":"我們在尋找熟練的工程師。"}]', '{"noun":"skill","adverb":"skillfully"}', NULL, 3, 2804, NULL),
(2805, 'SLA', '/ˌes el ˈeɪ/', 'noun', '{"zh-TW":["服務水準協議"],"en":["service level agreement; a contract defining the expected level of service"]}', NULL, 'meet the SLA / breach the SLA / SLA requirements / SLA penalty', '[{"en":"The vendor failed to meet the SLA for system uptime.","zh-TW":"供應商未能達到系統正常運行時間的服務水準協議。"},{"en":"A strict SLA ensures the provider maintains quality standards.","zh-TW":"嚴格的服務水準協議確保供應商維持品質標準。"}]', '{"full form":"service level agreement"}', NULL, 1, 2805, NULL),
(2806, 'sleep', '/sliːp/', 'verb', '{"zh-TW":["睡覺"],"en":["to rest with eyes closed and mind unconscious"]}', NULL, 'lose sleep over / sleep on it', '[{"en":"Don''t lose sleep over this issue.","zh-TW":"不要因為這個問題而失眠。"},{"en":"Let me sleep on it and decide tomorrow.","zh-TW":"讓我考慮一晚，明天再決定。"}]', '{"verb":"sleep","noun":"sleep","adjective":"sleepy","adjective2":"sleepless"}', NULL, 2, 2806, NULL),
(2807, 'slight', '/slaɪt/', 'adjective', '{"zh-TW":["輕微的；些微的"],"en":["small in degree; not important"]}', NULL, 'slight increase / slight delay / slight difference', '[{"en":"There was a slight delay in the shipment.","zh-TW":"貨物有些微的延遲。"},{"en":"We noticed a slight improvement in performance.","zh-TW":"我們注意到效能有些微的改善。"}]', '{"adjective":"slight","adverb":"slightly"}', NULL, 2, 2807, NULL),
(2808, 'slow', '/sloʊ/', 'adjective', '{"zh-TW":["慢的；緩慢的"],"en":["not moving fast","taking a long time"]}', NULL, 'slow down / slow growth', '[{"en":"Economic growth has slowed down.","zh-TW":"經濟成長放緩了。"},{"en":"The approval process is very slow.","zh-TW":"審批流程非常緩慢。"}]', '{"adjective":"slow","verb":"slow","adverb":"slowly","noun":"slowdown"}', NULL, 1, 2808, NULL),
(2809, 'small', '/smɔːl/', 'adjective', '{"zh-TW":["小的"],"en":["not large in size or amount"]}', NULL, 'small business / small talk', '[{"en":"We support small businesses.","zh-TW":"我們支持小型企業。"},{"en":"Make small talk before the meeting starts.","zh-TW":"會議開始前閒聊一下。"}]', '{"adjective":"small","noun":"smallness"}', NULL, 2, 2809, NULL),
(2810, 'smart', '/smɑːrt/', 'adjective', '{"zh-TW":["聰明的；智能的"],"en":["intelligent","using advanced technology"]}', NULL, 'smart decision / smart phone', '[{"en":"That was a smart business decision.","zh-TW":"那是一個聰明的商業決策。"},{"en":"Smart technology improves efficiency.","zh-TW":"智能科技提高了效率。"}]', '{"adjective":"smart","adverb":"smartly","noun":"smartphone"}', NULL, 2, 2810, NULL),
(2811, 'smile', '/smaɪl/', 'verb', '{"zh-TW":["微笑"],"en":["to form a pleased expression with the mouth"]}', NULL, 'smile at / with a smile', '[{"en":"She greeted every customer with a smile.","zh-TW":"她面帶微笑地迎接每位顧客。"},{"en":"Service with a smile makes a difference.","zh-TW":"帶著微笑的服務會有不同。"}]', '{"verb":"smile","noun":"smile"}', NULL, 2, 2811, NULL),
(2812, 'smooth', 'smuːð', 'adjective', '{"zh-TW":["順暢的；平穩的","流暢的"],"en":["free from difficulties","happening without problems"]}', NULL, 'smooth transition/smooth process', '[{"en":"We ensured a smooth project handover.","zh-TW":"我們確保了順暢的專案交接。"}]', '{"adverb":"smoothly"}', NULL, 2, 2812, NULL),
(2813, 'snack', '/snæk/', 'noun', '{"zh-TW":["零食；小吃"],"en":["a small amount of food eaten between meals"]}', NULL, 'light snack / snack bar', '[{"en":"She grabbed a snack from the vending machine.","zh-TW":"她從自動販賣機拿了零食。"},{"en":"The flight included a complimentary snack and drink.","zh-TW":"航班包含免費零食和飲料。"}]', '{"verb":"snack"}', NULL, 2, 2813, NULL),
(2814, 'snow', '/snoʊ/', 'noun', '{"zh-TW":["雪"],"en":["frozen water falling from the sky"]}', NULL, 'snowball effect / snowed under', '[{"en":"I am snowed under with work this week.","zh-TW":"我這週工作堆積如山。"},{"en":"The issue had a snowball effect.","zh-TW":"這個問題產生了滾雪球效應。"}]', '{"noun":"snow","adjective":"snowy","verb":"snow"}', NULL, 1, 2814, NULL),
(2815, 'soar', '/sɔːr/', 'verb', '{"zh-TW":["飆升；暴漲","翱翔"],"en":["to rise rapidly; to fly high"]}', NULL, 'soar to new heights / prices soar / profits soar', '[{"en":"Fuel prices soared by 30% this quarter.","zh-TW":"本季燃油價格飆升了30%。"},{"en":"The company''s stock price soared after the announcement.","zh-TW":"公告後公司股價飆升。"}]', '{"verb":"soar","adjective":"soaring"}', NULL, 1, 2815, NULL),
(2816, 'society', 'səˈsaɪəti', 'noun', '{"zh-TW":["社會；社團","協會"],"en":["the community of people","an organization"]}', NULL, 'modern society/civil society', '[{"en":"Technology plays a huge role in modern society.","zh-TW":"技術在現代社會中扮演著重要角色。"}]', '{"adjective":"social","adverb":"socially"}', NULL, 3, 2816, NULL),
(2817, 'soft', '/sɒft/', 'adjective', '{"zh-TW":["軟的；柔和的"],"en":["not hard","gentle"]}', NULL, 'soft skills / software', '[{"en":"Soft skills are as important as technical skills.","zh-TW":"軟實力和技術能力一樣重要。"},{"en":"The soft launch went smoothly.","zh-TW":"軟性上市進行順利。"}]', '{"adjective":"soft","verb":"soften","noun":"software","adverb":"softly"}', NULL, 1, 2817, NULL),
(2818, 'software', '/ˈsɒftwɛr/', 'noun', '{"zh-TW":["軟體"],"en":["programs used by a computer"]}', NULL, 'software update / software engineer', '[{"en":"Install the latest software update.","zh-TW":"安裝最新的軟體更新。"},{"en":"She develops educational software.","zh-TW":"她開發教育軟體。"}]', NULL, NULL, 3, 2818, 458),
(2819, 'sole', '/soʊl/', 'adjective', '{"zh-TW":["唯一的；獨有的"],"en":["one and only; exclusive"]}', NULL, 'sole purpose / sole responsibility / sole proprietor', '[{"en":"She is the sole owner of the company.","zh-TW":"她是公司的唯一所有人。"},{"en":"The sole purpose of the meeting was budget approval.","zh-TW":"會議的唯一目的是預算審批。"}]', '{"adjective":"sole","adverb":"solely"}', NULL, 1, 2819, NULL),
(2820, 'solicit', '/səˈlɪsɪt/', 'verb', '{"zh-TW":["徵求；請求"],"en":["to ask for something earnestly"]}', NULL, 'solicit feedback / solicit bids / solicit opinions', '[{"en":"The company solicited feedback from its customers.","zh-TW":"公司向客戶徵求回饋。"},{"en":"We solicited bids from multiple vendors.","zh-TW":"我們向多家供應商徵求報價。"}]', '{"noun":"solicitation","verb":"solicit"}', NULL, 3, 2820, 721),
(2821, 'solidify', '/səˈlɪdɪfaɪ/', 'verb', '{"zh-TW":["鞏固；使堅固"],"en":["to make or become firm or strong"]}', NULL, 'solidify one''s position / solidify partnerships', '[{"en":"The merger solidified the company''s market position.","zh-TW":"合併鞏固了公司的市場地位。"},{"en":"We aim to solidify our partnerships in the region.","zh-TW":"我們旨在鞏固在該地區的合作夥伴關係。"}]', '{"noun":"solidarity","verb":"solidify","adjective":"solid"}', NULL, 3, 2821, NULL),
(2822, 'solution', 'səˈluːʃən', 'noun', '{"zh-TW":["解決方案；答案","溶液"],"en":["a way of solving a problem","an answer to a question"]}', NULL, 'find a solution/cost-effective solution', '[{"en":"We need a cost-effective solution.","zh-TW":"我們需要一個具有成本效益的解決方案。"}]', '{"verb":"solve","adjective":"solvable"}', NULL, 3, 2822, 217),
(2823, 'solve', '/sɑːlv/', 'verb', '{"zh-TW":["解決；解答"],"en":["to find an answer to a problem"]}', NULL, 'solve a problem / solve an issue / problem-solving', '[{"en":"We need to solve this issue before launch.","zh-TW":"我們需要在上線前解決這個問題。"},{"en":"The team solved the technical challenge quickly.","zh-TW":"團隊很快解決了技術挑戰。"}]', '{"noun":"solution","verb":"solve","adjective":"solvable, unsolved"}', NULL, 2, 2823, NULL),
(2824, 'solvency', '/ˈsɒlvənsi/', 'noun', '{"zh-TW":["償債能力"],"en":["the ability to meet long-term financial obligations"]}', NULL, 'maintain solvency / solvency ratio / test of solvency', '[{"en":"The bank passed the solvency test with comfortable margins.","zh-TW":"銀行以舒適的空間通過了償債能力測試。"},{"en":"Declining sales raised concerns about the firm''s solvency.","zh-TW":"銷售額下降引發了對公司償債能力的擔憂。"}]', '{"adjective":"solvent","antonym":"insolvent"}', NULL, 3, 2824, NULL),
(2825, 'somewhat', '/ˈsʌmwɑːt/', 'adverb', '{"zh-TW":["有點；稍微"],"en":["to some extent; a little"]}', NULL, 'somewhat different / somewhat surprising / somewhat difficult', '[{"en":"The results were somewhat disappointing.","zh-TW":"結果有點令人失望。"},{"en":"The process is somewhat more complex than expected.","zh-TW":"這個流程比預期的稍微複雜一些。"}]', '{"adverb":"somewhat"}', NULL, 3, 2825, NULL),
(2826, 'sommelier', '/ˌsɒməˈljeɪ/', 'noun', '{"zh-TW":["侍酒師"],"en":["a wine expert who advises on wine in a restaurant"]}', NULL, 'consult the sommelier / ask the sommelier', '[{"en":"The sommelier recommended a local wine with the fish dish.","zh-TW":"侍酒師推薦了一款配魚料理的當地葡萄酒。"},{"en":"A skilled sommelier enhances the dining experience.","zh-TW":"熟練的侍酒師提升了用餐體驗。"}]', NULL, NULL, 3, 2826, NULL),
(2827, 'son', '/sʌn/', 'noun', '{"zh-TW":["兒子"],"en":["a male child"]}', NULL, 'only son / son-in-law', '[{"en":"His son joined the family business.","zh-TW":"他的兒子加入了家族企業。"},{"en":"My son-in-law works in accounting.","zh-TW":"我的女婿在會計部門工作。"}]', '{"noun":"son"}', NULL, 1, 2827, NULL),
(2828, 'soon', '/suːn/', 'adverb', '{"zh-TW":["很快；不久"],"en":["in a short time"]}', NULL, 'as soon as / sooner or later', '[{"en":"We will launch as soon as possible.","zh-TW":"我們會盡快推出。"},{"en":"Sooner or later, the truth will come out.","zh-TW":"遲早真相會水落石出。"}]', '{"adverb":"soon","adjective":"soon"}', NULL, 1, 2828, NULL),
(2829, 'sophisticated', '/səˈfɪstɪkeɪtɪd/', 'adjective', '{"zh-TW":["精密的；複雜的","世故的"],"en":["highly developed and complex","having refined taste"]}', NULL, 'sophisticated technology / sophisticated system / sophisticated approach', '[{"en":"The company uses sophisticated data analytics.","zh-TW":"公司使用精密的數據分析。"},{"en":"This requires a more sophisticated approach.","zh-TW":"這需要更精密的方法。"}]', '{"noun":"sophistication","adjective":"sophisticated"}', NULL, 5, 2829, NULL),
(2830, 'sophomore', '/ˈsɒfəmɔːr/', 'noun', '{"zh-TW":["大二學生"],"en":["a second-year student"]}', NULL, 'sophomore year / sophomore album', '[{"en":"She''s a sophomore in college.","zh-TW":"她是大二學生。"},{"en":"His sophomore year was the hardest.","zh-TW":"他的大二是最辛苦的。"}]', NULL, NULL, 3, 2830, NULL),
(2831, 'sorry', '/ˈsɒri/', 'adjective', '{"zh-TW":["抱歉的"],"en":["feeling regret or apology"]}', NULL, 'sorry for / sorry to hear', '[{"en":"I am sorry for the inconvenience.","zh-TW":"很抱歉造成不便。"},{"en":"Sorry to hear about the delay.","zh-TW":"很遺憾聽到延遲的消息。"}]', '{"adjective":"sorry"}', NULL, 2, 2831, NULL),
(2832, 'sort', 'sɔːrt', 'verb', '{"zh-TW":["整理；排序","分類"],"en":["to put in order","to separate into groups"]}', NULL, 'sort files/sort by date', '[{"en":"Please sort the files alphabetically.","zh-TW":"請按字母順序整理文件。"}]', '{"noun":"sort, sorting","adjective":"sorted"}', NULL, 1, 2832, NULL),
(2833, 'sound', '/saʊnd/', 'noun', '{"zh-TW":["【主要意義-名詞】聲音；聲響","【次要意義-形容詞】健全的；穩固的；合理的；可靠的","【次要意義-副詞】徹底地（如 sound asleep）"],"en":["[primary - noun] vibrations that travel through air and are heard","[secondary - adjective] in good condition; reliable and sensible","[secondary - adverb] deeply and completely"]}', NULL, 'sound advice / sound investment / sound asleep / of sound mind', '[{"en":"The board agreed that it was a sound investment decision.","zh-TW":"董事會認為這是一個穩健的投資決定。"},{"en":"The auditor confirmed that the company finances were perfectly sound.","zh-TW":"審計師確認公司財務狀況完全健全。"},{"en":"He was sound asleep when the emergency call came through.","zh-TW":"當緊急電話打來時，他睡得正熟。"}]', '{"adverb":"soundly","noun":"soundness"}', '形容詞 sound = 「穩健的/健全的/合理的」，sound advice（正確建議）、sound investment（穩健投資）、sound judgment（合理判斷）是 TOEIC 財務和管理文章的高頻表達。', 2, 2833, NULL),
(2834, 'source', '/sɔːrs/', 'noun, verb', '{"zh-TW":["來源；出處","採購；尋找來源"],"en":["a place from which something comes","to obtain from a particular place"]}', NULL, 'reliable source / source of income / source materials', '[{"en":"Tourism is the main source of income for the region.","zh-TW":"旅遊業是該地區的主要收入來源。"},{"en":"We source our materials from local suppliers.","zh-TW":"我們從當地供應商採購材料。"}]', '{"noun":"source","verb":"source, outsource"}', NULL, 2, 2834, NULL),
(2835, 'sourcing', '/ˈsɔːrsɪŋ/', 'noun', '{"zh-TW":["採購；尋源"],"en":["finding and selecting suppliers for goods or services"]}', NULL, 'strategic sourcing / global sourcing / sourcing process', '[{"en":"The sourcing team identified five potential suppliers for the component.","zh-TW":"採購團隊為該零件識別了五個潛在供應商。"},{"en":"Offshore sourcing reduced material costs by 30%.","zh-TW":"境外採購將材料成本降低了30%。"}]', '{"verb":"source","adjective":"sourced"}', NULL, 3, 2835, NULL),
(2836, 'space', '/speɪs/', 'noun', '{"zh-TW":["空間；太空"],"en":["an area available for use","the universe beyond Earth"]}', NULL, 'office space / co-working space', '[{"en":"We are looking for new office space.","zh-TW":"我們正在尋找新的辦公空間。"},{"en":"Co-working spaces are popular with startups.","zh-TW":"共同工作空間很受新創公司歡迎。"}]', '{"noun":"space","adjective":"spacious","verb":"space"}', NULL, 2, 2836, NULL),
(2837, 'span', '/spæn/', 'noun, verb', '{"zh-TW":["跨度；時間段","跨越"],"en":["the full extent of something","to extend across"]}', NULL, 'time span / attention span / span a period', '[{"en":"The project spans a period of three years.","zh-TW":"該專案跨越三年時間。"},{"en":"The average attention span is decreasing.","zh-TW":"平均注意力持續時間正在減少。"}]', '{"noun":"span","verb":"span"}', NULL, 1, 2837, NULL),
(2838, 'spare', '/sper/', 'adjective, verb', '{"zh-TW":["【主要意義-動詞】省去；免除；撥出（時間）","【次要意義-形容詞】多餘的；備用的；空閒的；瘦的","【次要意義-名詞】備用品；備胎"],"en":["[primary - verb] to make something available; to refrain from harming","[secondary - adjective] extra, not currently in use; lean and thin","[secondary - noun] a spare part or tire"]}', NULL, 'spare time / spare room / spare tire / spare no expense / to spare', '[{"en":"Could you spare a few minutes to review this proposal?","zh-TW":"您能撥出幾分鐘時間審閱這份提案嗎？"},{"en":"We have a spare conference room available on the third floor.","zh-TW":"三樓有一個空餘的會議室可供使用。"},{"en":"The company spared no expense in redesigning the headquarters.","zh-TW":"公司不惜重金重新設計總部。"}]', '{"adverb":"sparingly","adjective":"sparing"}', 'spare 最常見陷阱是形容詞用法「備用的/多餘的」及片語 spare no expense（不惜代價），TOEIC 閱讀中常見描述資源調度或設施的語境。', 2, 2838, NULL),
(2839, 'speak', '/spiːk/', 'verb', '{"zh-TW":["說話；發言"],"en":["to talk","to address an audience"]}', NULL, 'speak up / so to speak', '[{"en":"Please speak up if you disagree.","zh-TW":"如果不同意請大聲說出來。"},{"en":"She will speak at the conference.","zh-TW":"她將在會議上演講。"}]', '{"verb":"speak","noun":"speaker","noun2":"speech"}', NULL, 2, 2839, NULL),
(2840, 'specialist', '/ˈspeʃəlɪst/', 'noun', '{"zh-TW":["專家；專業人員"],"en":["a person with expert knowledge in a particular field"]}', NULL, 'HR specialist / marketing specialist / technical specialist', '[{"en":"The company hired a cybersecurity specialist to strengthen its defenses.","zh-TW":"公司聘請了網路安全專家加強防禦。"},{"en":"She became a specialist in supply chain optimization.","zh-TW":"她成為供應鏈優化方面的專家。"}]', '{"plural":"specialists","adjective":"specialized"}', NULL, 4, 2840, NULL),
(2841, 'specialty', '/ˈspɛʃəlti/', 'noun', '{"zh-TW":["特色菜；招牌菜"],"en":["a food item for which a place is particularly known"]}', NULL, 'house specialty / regional specialty', '[{"en":"The lobster bisque is the restaurant''s specialty.","zh-TW":"龍蝦濃湯是餐廳的招牌菜。"},{"en":"Try the local specialty when visiting a new city.","zh-TW":"造訪新城市時嘗試當地特色菜。"}]', '{"adjective":"special"}', NULL, 3, 2841, NULL),
(2842, 'specific', '/spɪˈsɪfɪk/', 'adjective', '{"zh-TW":["具體的；明確的","特定的"],"en":["clearly defined or identified","particular"]}', NULL, 'specific requirements / specific details / industry-specific', '[{"en":"Please provide specific examples.","zh-TW":"請提供具體的例子。"},{"en":"The instructions are very specific.","zh-TW":"指示非常明確。"}]', '{"noun":"specification, specifics","adjective":"specific","adverb":"specifically"}', NULL, 3, 2842, NULL),
(2843, 'specification', '/ˌspesɪfɪˈkeɪʃn/', 'noun', '{"zh-TW":["規格；規範"],"en":["a detailed description of requirements"]}', NULL, 'technical specifications / meet specifications / product specifications', '[{"en":"The product must meet the client''s specifications.","zh-TW":"產品必須符合客戶的規格。"},{"en":"Please review the technical specifications document.","zh-TW":"請審閱技術規格文件。"}]', '{"noun":"specification","verb":"specify","adjective":"specific"}', NULL, 5, 2843, 459),
(2844, 'specify', '/ˈspesɪfaɪ/', 'verb', '{"zh-TW":["指定；詳細說明"],"en":["to state explicitly or in detail"]}', '{"suffix":{"text":"-ify","meaning":"使..."}}', 'specify requirements / as specified / specify the terms', '[{"en":"The contract specifies the delivery date.","zh-TW":"合約中明確指定了交貨日期。"},{"en":"Please specify your preferred payment method.","zh-TW":"請指定您偏好的付款方式。"}]', '{"noun":"specification","verb":"specify","adjective":"specific, specified"}', NULL, 3, 2844, 218),
(2845, 'spectator', '/ˈspɛkteɪtər/', 'noun', '{"zh-TW":["觀眾；旁觀者"],"en":["a person who watches a game or event"]}', NULL, 'spectator sport / thousands of spectators', '[{"en":"Thousands of spectators filled the stadium.","zh-TW":"數千名觀眾坐滿了體育場。"},{"en":"Football is a popular spectator sport.","zh-TW":"足球是一項受歡迎的觀賞性運動。"}]', NULL, NULL, 3, 2845, NULL),
(2846, 'speculate', '/ˈspekjuleɪt/', 'verb', '{"zh-TW":["推測；猜測","投機"],"en":["to form a theory without firm evidence","to invest in risky ventures"]}', NULL, 'speculate on / speculate about / speculate in stocks', '[{"en":"Analysts speculate that the merger will proceed.","zh-TW":"分析師推測合併將繼續進行。"},{"en":"He speculated in the stock market.","zh-TW":"他在股市進行投機。"}]', '{"noun":"speculation, speculator","verb":"speculate","adjective":"speculative"}', NULL, 3, 2846, NULL),
(2847, 'speed', '/spiːd/', 'noun', '{"zh-TW":["速度"],"en":["how fast something moves"]}', NULL, 'at full speed / speed up', '[{"en":"We need to speed up production.","zh-TW":"我們需要加快生產速度。"},{"en":"The project is moving at full speed.","zh-TW":"專案正在全速推進。"}]', '{"noun":"speed","verb":"speed","adjective":"speedy","adverb":"speedily"}', NULL, 2, 2847, NULL),
(2848, 'spend', '/spɛnd/', 'verb', '{"zh-TW":["花費；消費"],"en":["to pay money","to use time"]}', NULL, 'spend money / spend time', '[{"en":"We spend 20% of revenue on R&D.","zh-TW":"我們將營收的20%用於研發。"},{"en":"Don''t spend too much time on this.","zh-TW":"不要在這上面花太多時間。"}]', '{"verb":"spend","noun":"spending","noun2":"expenditure"}', NULL, 2, 2848, NULL),
(2849, 'sphere', '/sfɪr/', 'noun', '{"zh-TW":["領域；範圍","球體"],"en":["an area of activity or influence","a round solid shape"]}', NULL, 'sphere of influence / public sphere / political sphere', '[{"en":"The decision falls within her sphere of influence.","zh-TW":"這個決定屬於她的影響範圍。"},{"en":"The company expanded into new spheres of business.","zh-TW":"公司擴展到新的商業領域。"}]', '{"noun":"sphere","adjective":"spherical"}', NULL, 2, 2849, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2850, 'spin-off', '/ˈspɪn ɒf/', 'noun', '{"zh-TW":["分拆；子公司獨立上市"],"en":["a new independent company created from a division of an existing company"]}', NULL, 'create a spin-off / spin-off company', '[{"en":"The tech division was spun off as a separate listed company.","zh-TW":"技術部門被分拆為一家獨立的上市公司。"},{"en":"Spin-offs allow each business to pursue strategies more suited to their sector.","zh-TW":"分拆允許每個業務追求更適合其行業的策略。"}]', '{"verb":"spin off"}', NULL, 3, 2850, NULL),
(2851, 'spinoff', '/ˈspɪnɒf/', 'noun', '{"zh-TW":["分拆；衍生公司"],"en":["a new company created by separating part of an existing company"]}', NULL, 'spinoff company / corporate spinoff', '[{"en":"The spinoff allowed each business to focus on its core.","zh-TW":"分拆讓每個業務能夠專注於其核心。"},{"en":"Shareholders received shares in the spinoff entity.","zh-TW":"股東獲得了分拆實體的股份。"}]', '{"verb":"spin off"}', NULL, 3, 2851, NULL),
(2852, 'sponsor', '/ˈspɑːnsər/', 'noun, verb', '{"zh-TW":["贊助者；贊助商","贊助"],"en":["a person or company that pays for an event","to financially support"]}', NULL, 'corporate sponsor / sponsor an event / main sponsor', '[{"en":"The event was sponsored by a major bank.","zh-TW":"活動由一家大型銀行贊助。"},{"en":"We are looking for sponsors for the conference.","zh-TW":"我們正在尋找會議的贊助商。"}]', '{"noun":"sponsor, sponsorship","verb":"sponsor"}', NULL, 3, 2852, 460),
(2853, 'sport', '/spɔːrt/', 'verb, noun, adjective', '{"zh-TW":["【主要意義】體育運動；娛樂消遣","【次要意義-動詞】炫耀地穿戴；誇示","【次要意義-名詞】光明磊落的人；有運動精神的人"],"en":["[primary] athletic activity or game","[secondary - verb] to wear or display something proudly or noticeably","[secondary - noun] a person who accepts defeat or teasing cheerfully"]}', NULL, 'sport a new hairstyle / sport a badge / be a good sport', '[{"en":"She sported a brand new designer handbag at the meeting.","zh-TW":"她在會議上炫耀地提著一個全新的設計師手提包。"},{"en":"He was a good sport about losing the competition.","zh-TW":"他輸了比賽後表現得很有運動精神。"},{"en":"The new employee sported a confident smile on his first day.","zh-TW":"新員工在第一天上班時臉上掛著自信的微笑。"}]', '{"noun":"sports, sportsmanship","adjective":"sporting, sporty"}', '動詞用法 sport = 炫耀地展示，常出現在描述外貌或穿著的語境中，TOEIC 閱讀常見陷阱。', 2, 2853, NULL),
(2854, 'spot', '/spɑːt/', 'noun, verb', '{"zh-TW":["地點；位置","發現；注意到"],"en":["a particular place","to notice or identify"]}', NULL, 'on the spot / spot a trend / weak spot', '[{"en":"She spotted an error in the financial report.","zh-TW":"她發現了財務報告中的一個錯誤。"},{"en":"The manager made a decision on the spot.","zh-TW":"經理當場做出了決定。"}]', '{"noun":"spot","verb":"spot"}', NULL, 1, 2854, NULL),
(2855, 'spread', '/spred/', 'verb, noun', '{"zh-TW":["擴散；傳播","擴展；差價"],"en":["to extend over a larger area","the extent or range of something"]}', NULL, 'spread awareness / spread across / spread the risk', '[{"en":"The company spread its operations across Asia.","zh-TW":"公司將業務擴展至亞洲各地。"},{"en":"We need to spread the investment risk.","zh-TW":"我們需要分散投資風險。"}]', '{"noun":"spread","verb":"spread"}', NULL, 2, 2855, NULL),
(2856, 'sprint', '/sprɪnt/', 'noun', '{"zh-TW":["衝刺；衝刺週期"],"en":["a short, time-boxed period in agile development to complete specific tasks"]}', NULL, 'run a sprint / sprint planning / sprint review / two-week sprint', '[{"en":"Each sprint lasts two weeks in the team''s agile process.","zh-TW":"在團隊的敏捷流程中，每個衝刺持續兩週。"},{"en":"The team completed all sprint goals ahead of schedule.","zh-TW":"團隊提前完成了所有衝刺目標。"}]', '{"verb":"sprint","adjective":"sprint-based"}', NULL, 2, 2856, NULL),
(2857, 'SQL', '/ˌes kjuː ˈel/', 'noun', '{"zh-TW":["銷售合格潛在客戶"],"en":["sales qualified lead; a prospect evaluated as ready for a direct sales approach"]}', NULL, 'convert to SQL / SQL pipeline / track SQLs', '[{"en":"Sales reps focus their efforts on SQLs to maximize conversion.","zh-TW":"銷售代表將精力集中在銷售合格潛在客戶上以最大化轉換。"},{"en":"The SQL rate improved after tightening the qualification criteria.","zh-TW":"收緊資格標準後，銷售合格潛在客戶率有所提高。"}]', '{"full form":"sales qualified lead"}', NULL, 1, 2857, NULL),
(2858, 'stabilize', '/ˈsteɪbəlaɪz/', 'verb', '{"zh-TW":["穩定；使穩定"],"en":["to make or become steady"]}', NULL, 'stabilize prices / stabilize the economy / stabilize the situation', '[{"en":"The government took measures to stabilize the currency.","zh-TW":"政府採取措施穩定貨幣。"},{"en":"Prices have finally stabilized after months of volatility.","zh-TW":"經過數月的波動，價格終於穩定下來。"}]', '{"noun":"stability, stabilization","verb":"stabilize","adjective":"stable"}', NULL, 3, 2858, 722),
(2859, 'stable', '/ˈsteɪbl/', 'adjective', '{"zh-TW":["穩定的；穩固的"],"en":["not likely to change; firmly established"]}', NULL, 'stable economy / stable income / financially stable', '[{"en":"The economy has remained relatively stable.","zh-TW":"經濟保持相對穩定。"},{"en":"A stable income is important for loan approval.","zh-TW":"穩定的收入對貸款審批很重要。"}]', '{"noun":"stability","verb":"stabilize","adjective":"stable, unstable","adverb":"stably"}', NULL, 2, 2859, NULL),
(2860, 'stadium', '/ˈsteɪdiəm/', 'noun', '{"zh-TW":["體育場"],"en":["a large area for sports events with seats around it"]}', NULL, 'football stadium / stadium tour', '[{"en":"The stadium holds 80,000 people.","zh-TW":"這座體育場可容納八萬人。"},{"en":"The new stadium was built last year.","zh-TW":"新體育場去年建成。"}]', NULL, NULL, 3, 2860, NULL),
(2861, 'staff', '/stæf/', 'noun, verb', '{"zh-TW":["員工；職員","配備人員"],"en":["the people who work for an organization","to provide with workers"]}', NULL, 'staff members / staff training / fully staffed', '[{"en":"All staff must attend the safety briefing.","zh-TW":"所有員工都必須參加安全簡報。"},{"en":"The office is fully staffed during business hours.","zh-TW":"辦公室在營業時間有完整的人員配置。"}]', '{"noun":"staff, staffing","verb":"staff"}', NULL, 2, 2861, 461),
(2862, 'staffing', '/ˈstæfɪŋ/', 'noun', '{"zh-TW":["人員配置；招募"],"en":["the process of hiring and placing workers in an organization"]}', NULL, 'staffing agency / staffing levels / staffing needs', '[{"en":"The project required a rapid increase in staffing levels.","zh-TW":"該項目需要迅速增加人員配置。"},{"en":"Staffing agencies provide temporary workers on short notice.","zh-TW":"人力仲介公司能在短時間內提供臨時工作人員。"}]', '{"verb":"staff","noun":"staff"}', NULL, 3, 2862, NULL),
(2863, 'stage', '/steɪdʒ/', 'noun, verb', '{"zh-TW":["階段；時期","舉辦；籌劃"],"en":["a point in a process","to organize and present"]}', NULL, 'at this stage / early stage / stage an event', '[{"en":"The project is still in the early stages.","zh-TW":"專案仍處於早期階段。"},{"en":"The company staged a product launch event.","zh-TW":"公司舉辦了一場產品發布活動。"}]', '{"noun":"stage","verb":"stage"}', NULL, 2, 2863, NULL),
(2864, 'stagnant', '/ˈstæɡnənt/', 'adjective', '{"zh-TW":["停滯的；不景氣的"],"en":["showing no activity or growth"]}', NULL, 'stagnant economy / stagnant wages / stagnant market', '[{"en":"Wages have remained stagnant for years.","zh-TW":"薪資已停滯多年。"},{"en":"The stagnant market offers few opportunities.","zh-TW":"停滯的市場提供很少的機會。"}]', '{"noun":"stagnation","verb":"stagnate","adjective":"stagnant"}', NULL, 3, 2864, NULL),
(2865, 'stake', '/steɪk/', 'noun', '{"zh-TW":["股份；利害關係","賭注"],"en":["a share or interest in a business","something risked"]}', NULL, 'at stake / stakeholder / have a stake in', '[{"en":"Millions of dollars are at stake.","zh-TW":"數百萬美元面臨風險。"},{"en":"She has a 20% stake in the company.","zh-TW":"她擁有公司20%的股份。"}]', '{"noun":"stake, stakeholder"}', NULL, 2, 2865, NULL),
(2866, 'stakeholder', '/ˈsteɪkhoʊldər/', 'noun', '{"zh-TW":["利害關係人"],"en":["a person with an interest or concern in something"]}', NULL, 'key stakeholders / stakeholder engagement / stakeholder management', '[{"en":"All stakeholders were consulted before the decision.","zh-TW":"做決定之前諮詢了所有利害關係人。"},{"en":"Stakeholder engagement is crucial for project success.","zh-TW":"利害關係人參與對專案成功至關重要。"}]', '{"noun":"stakeholder, stake"}', NULL, 4, 2866, 934),
(2867, 'stand', '/stænd/', 'verb', '{"zh-TW":["【主要意義-動詞】站立","【次要意義-動詞】忍受；容忍","【次要意義-名詞】立場；態度；主張","【次要意義-名詞】攤位；展台；貨架"],"en":["[primary] to be in an upright position","[secondary - verb] to tolerate or endure without objection","[secondary - noun] a position or attitude toward an issue","[secondary - noun] a small structure where things are sold or displayed"]}', NULL, 'take a stand / stand firm / stand for / exhibition stand / music stand', '[{"en":"The company took a firm stand against using suppliers with poor labor practices.","zh-TW":"公司對使用勞動條件惡劣的供應商採取了堅定的立場。"},{"en":"Our products will be displayed at Stand 24B at the trade fair.","zh-TW":"我們的產品將在貿易展覽會的24B號攤位展出。"},{"en":"I cannot stand the way the new system slows down productivity.","zh-TW":"我無法忍受新系統降低生產力的方式。"}]', '{"noun":"standpoint, standstill","adjective":"outstanding"}', 'stand 作動詞表「忍受」，作名詞表「立場」或「展台攤位」，TOEIC 展覽/貿易類文章常見 stand（攤位），take a stand（表明立場）出現在商業決策文章中。', 2, 2867, NULL),
(2868, 'standalone', '/ˈstænəloʊn/', 'adjective', '{"zh-TW":["獨立的；自立的"],"en":["operating independently without relying on other systems or entities"]}', NULL, 'standalone entity / standalone business / standalone solution', '[{"en":"The division was spun off as a standalone business.","zh-TW":"該部門被分拆為一個獨立業務。"},{"en":"A standalone software system runs without requiring other applications.","zh-TW":"獨立的軟件系統在不需要其他應用程序的情況下運行。"}]', NULL, NULL, 4, 2868, NULL),
(2869, 'standard', '/ˈstændərd/', 'noun, adjective', '{"zh-TW":["標準；水準","標準的；普通的"],"en":["a level of quality","usual or normal"]}', NULL, 'industry standard / standard procedure / set a standard', '[{"en":"Our products meet international quality standards.","zh-TW":"我們的產品符合國際品質標準。"},{"en":"This is standard procedure for all new hires.","zh-TW":"這是所有新進員工的標準程序。"}]', '{"noun":"standard, standardization","verb":"standardize","adjective":"standard"}', NULL, 3, 2869, 219),
(2870, 'standardization', '/ˌstændərdɪˈzeɪʃən/', 'noun', '{"zh-TW":["標準化"],"en":["the process of establishing uniform specifications or methods"]}', NULL, 'pursue standardization / standardization of processes', '[{"en":"Standardization of forms reduced administrative errors by 20%.","zh-TW":"表格的標準化將行政錯誤減少了20%。"},{"en":"Product standardization simplifies manufacturing and reduces costs.","zh-TW":"產品標準化簡化了製造並降低了成本。"}]', '{"verb":"standardize","adjective":"standardized"}', NULL, 5, 2870, 622),
(2871, 'standardize', 'ˈstændərdaɪz', 'verb', '{"zh-TW":["標準化；統一","規範化"],"en":["to make uniform","to apply a standard"]}', NULL, 'standardize processes/standardize formats', '[{"en":"We need to standardize the reporting format.","zh-TW":"我們需要標準化報告格式。"}]', '{"noun":"standardization","adjective":"standardized"}', NULL, 4, 2871, NULL),
(2872, 'standpoint', '/ˈstændpɔɪnt/', 'noun', '{"zh-TW":["觀點；立場"],"en":["a particular attitude or way of considering something"]}', NULL, 'from a standpoint / financial standpoint / legal standpoint', '[{"en":"From a financial standpoint, the deal makes sense.","zh-TW":"從財務的角度來看，這筆交易是合理的。"},{"en":"From the customer''s standpoint, the change is positive.","zh-TW":"從客戶的角度來看，這個改變是正面的。"}]', '{"noun":"standpoint"}', NULL, 4, 2872, NULL),
(2873, 'star', '/stɑːr/', 'noun', '{"zh-TW":["明星；星星"],"en":["a famous person","a bright point of light in the sky"]}', NULL, 'star performer / five-star', '[{"en":"She is a star performer on the team.","zh-TW":"她是團隊中的明星成員。"},{"en":"We stayed at a five-star hotel.","zh-TW":"我們住在一家五星級飯店。"}]', '{"noun":"star","adjective":"star","adjective2":"stellar"}', NULL, 1, 2873, NULL),
(2874, 'start', '/stɑːrt/', 'verb', '{"zh-TW":["開始；創辦"],"en":["to begin","to set up a company"]}', NULL, 'start a business / from the start', '[{"en":"She started the company in her garage.","zh-TW":"她在車庫裡創辦了這家公司。"},{"en":"We knew from the start it would be difficult.","zh-TW":"我們從一開始就知道會很困難。"}]', '{"verb":"start","noun":"start","noun2":"startup","noun3":"starter"}', NULL, 2, 2874, NULL),
(2875, 'startup', '/ˈstɑːrtʌp/', 'noun', '{"zh-TW":["新創公司"],"en":["a newly established business"]}', NULL, 'tech startup / startup culture', '[{"en":"He founded a tech startup.","zh-TW":"他創立了一家科技新創公司。"},{"en":"The startup raised millions in funding.","zh-TW":"這家新創公司籌集了數百萬資金。"}]', NULL, NULL, 3, 2875, NULL),
(2876, 'state', '/steɪt/', 'noun, verb', '{"zh-TW":["【主要意義-名詞】州；國家；狀態","【次要意義-動詞】說明；陳述；正式聲明","【次要意義-形容詞】國家的；官方的；正式的"],"en":["[primary - noun] a region or nation; a condition","[secondary - verb] to express something clearly and formally","[secondary - adjective] relating to the government or official ceremony"]}', NULL, 'state clearly / state that / state of affairs / state-of-the-art', '[{"en":"Please state your reason for requesting an extension in writing.","zh-TW":"請以書面說明您申請延期的原因。"},{"en":"The contract clearly states that all changes must be approved in advance.","zh-TW":"合約明確規定，所有變更必須事先獲得批准。"},{"en":"She stated that she had no prior knowledge of the financial irregularities.","zh-TW":"她聲明她事先不知道財務違規情況。"}]', '{"noun":"statement","adjective":"stated"}', '動詞 state = 「正式陳述/說明」，比 say 更正式，常見於合約或法律文件語境（as stated in the contract），是 TOEIC 閱讀最高頻動詞之一。', 2, 2876, NULL),
(2877, 'statement', '/ˈsteɪtmənt/', 'noun', '{"zh-TW":["帳單；聲明；陳述"],"en":["a document showing financial transactions over a period"]}', NULL, 'bank statement / review a statement', '[{"en":"Please review your monthly bank statement carefully.","zh-TW":"請仔細查看您的每月銀行帳單。"},{"en":"The accountant prepared a financial statement for the year.","zh-TW":"會計師準備了年度財務報表。"}]', '{"verb":"state","adjective":"stated"}', NULL, 3, 2877, 220),
(2878, 'statistic', '/stəˈtɪstɪk/', 'noun', '{"zh-TW":["統計數據；統計資料"],"en":["numerical data collected for analysis"]}', NULL, 'official statistics / statistical analysis / according to statistics', '[{"en":"Statistics show a decline in unemployment.","zh-TW":"統計數據顯示失業率下降。"},{"en":"We need statistical evidence to support the claim.","zh-TW":"我們需要統計證據來支持這項主張。"}]', '{"noun":"statistic, statistics","adjective":"statistical","adverb":"statistically"}', NULL, 3, 2878, NULL),
(2879, 'status', '/ˈsteɪtəs/', 'noun', '{"zh-TW":["地位；身分","狀態；情形"],"en":["relative social or professional position","the current situation"]}', NULL, 'status update / social status / status quo', '[{"en":"Please provide a status update on the project.","zh-TW":"請提供專案的狀態更新。"},{"en":"The company wants to maintain the status quo.","zh-TW":"公司想維持現狀。"}]', '{"noun":"status"}', NULL, 2, 2879, 221),
(2880, 'statute', '/ˈstætʃuːt/', 'noun', '{"zh-TW":["法規；法令"],"en":["a written law passed by a legislature","a written law passed by a legislative body"]}', NULL, 'statute of limitations / by statute; by statute / statute of limitations / federal statute', '[{"en":"The statute of limitations has expired.","zh-TW":"追訴時效已過。"},{"en":"It''s required by statute.","zh-TW":"這是法規要求的。"},{"en":"The regulation is required by statute.","zh-TW":"該法規是法律要求的。"},{"en":"The statute of limitations has expired.","zh-TW":"訴訟時效已過期。"}]', '{"adjective":"statutory","noun":"statute"}', NULL, 3, 2880, NULL),
(2881, 'statutory', '/ˈstætʃətɔːri/', 'adjective', '{"zh-TW":["法定的；依法規定的"],"en":["required or imposed by law"]}', NULL, 'statutory requirement / statutory obligations / statutory holiday', '[{"en":"Companies must comply with all statutory reporting requirements.","zh-TW":"公司必須遵守所有法定報告要求。"},{"en":"Employees are entitled to statutory sick pay under labor law.","zh-TW":"員工依勞動法有權獲得法定病假工資。"}]', '{"adverb":"statutorily","noun":"statute"}', NULL, 3, 2881, 935),
(2882, 'stay', '/steɪ/', 'verb', '{"zh-TW":["停留；保持"],"en":["to remain in a place","to continue in a state"]}', NULL, 'stay focused / stay in touch', '[{"en":"Stay focused on the goals.","zh-TW":"專注於目標。"},{"en":"Let''s stay in touch.","zh-TW":"讓我們保持聯繫。"}]', '{"verb":"stay","noun":"stay"}', NULL, 1, 2882, NULL),
(2883, 'stayover', '/ˈsteɪoʊvər/', 'noun', '{"zh-TW":["延長住宿"],"en":["a guest who extends their stay beyond the original checkout date"]}', NULL, 'process a stayover / stayover extension', '[{"en":"She requested a stayover to extend her booking by one night.","zh-TW":"她要求延長住宿，將預訂延長一晚。"},{"en":"Stayovers are handled automatically if the room is available.","zh-TW":"如果房間有空，延長住宿將自動處理。"}]', NULL, NULL, 3, 2883, NULL),
(2884, 'steady', '/ˈstedi/', 'adjective', '{"zh-TW":["穩定的；持續的"],"en":["regular and continuous; not changing"]}', NULL, 'steady growth / steady income / steady progress', '[{"en":"The company has shown steady growth over five years.","zh-TW":"公司在五年內呈現穩定增長。"},{"en":"We are making steady progress on the project.","zh-TW":"我們在專案上穩步前進。"}]', '{"noun":"steadiness","adjective":"steady","adverb":"steadily"}', NULL, 2, 2884, NULL),
(2885, 'steep', '/stiːp/', 'adjective', '{"zh-TW":["陡峭的；急劇的"],"en":["rising or falling sharply; very high"]}', NULL, 'steep increase / steep decline / steep price', '[{"en":"There was a steep decline in profits.","zh-TW":"利潤急劇下降。"},{"en":"The learning curve is quite steep.","zh-TW":"學習曲線相當陡峭。"}]', '{"adjective":"steep","adverb":"steeply"}', NULL, 2, 2885, NULL),
(2886, 'stem', '/stem/', 'verb, noun', '{"zh-TW":["起源於；阻止","莖；幹"],"en":["to originate from; to stop","the main body of a plant"]}', NULL, 'stem from / stem the tide / stem cell', '[{"en":"The problem stems from poor planning.","zh-TW":"這個問題源於規劃不良。"},{"en":"We must stem the flow of losses.","zh-TW":"我們必須遏止虧損的趨勢。"}]', '{"noun":"stem","verb":"stem"}', NULL, 1, 2886, NULL),
(2887, 'step', '/stɛp/', 'noun', '{"zh-TW":["步驟；一步"],"en":["a movement of the foot","a stage in a process"]}', NULL, 'step by step / next step', '[{"en":"Let''s go through the process step by step.","zh-TW":"讓我們一步一步地完成流程。"},{"en":"What is the next step?","zh-TW":"下一步是什麼？"}]', '{"noun":"step","verb":"step"}', NULL, 1, 2887, NULL),
(2888, 'still', '/stɪl/', 'noun, adjective, adverb, verb', '{"zh-TW":["【主要意義-副詞】仍然；還是","【次要意義-名詞】蒸餾器（釀酒設備）","【次要意義-名詞】靜物畫；電影劇照","【次要意義-動詞】使平靜；使安靜"],"en":["[primary - adverb] up to this time; even now","[secondary - noun] apparatus for making alcohol by distillation","[secondary - noun] a single photograph from a film or video","[secondary - verb] to make quiet or calm"]}', NULL, 'still life / distilling still / still the crowd / keep still', '[{"en":"The director selected a still from the film for the promotional poster.","zh-TW":"導演從電影中選了一張劇照用於宣傳海報。"},{"en":"The company operates a whisky still in the Scottish Highlands.","zh-TW":"這家公司在蘇格蘭高地經營一台威士忌蒸餾器。"},{"en":"Her calm words stilled the anxious crowd.","zh-TW":"她平靜的話語讓焦慮的人群安靜下來。"}]', '{"noun":"stillness","adjective":"still"}', 'still 作名詞意為「蒸餾器」或「劇照」，動詞表「使平靜」，這些次要意義在 TOEIC 飲食業或媒體相關文章中偶爾出現，容易讓考生困惑。', 2, 2888, NULL),
(2889, 'stimulate', '/ˈstɪmjuleɪt/', 'verb', '{"zh-TW":["刺激；激勵"],"en":["to encourage activity or development"]}', NULL, 'stimulate growth / stimulate the economy / stimulate demand', '[{"en":"The government introduced measures to stimulate the economy.","zh-TW":"政府推出了刺激經濟的措施。"},{"en":"Lower prices stimulate consumer demand.","zh-TW":"較低的價格刺激了消費者需求。"}]', '{"noun":"stimulation, stimulus","verb":"stimulate","adjective":"stimulating"}', NULL, 3, 2889, NULL),
(2890, 'stipulate', '/ˈstɪpjʊleɪt/', 'verb', '{"zh-TW":["規定；明確要求"],"en":["to specify a condition or requirement as part of an agreement"]}', NULL, 'stipulate terms / stipulate conditions / as stipulated', '[{"en":"The contract stipulates that payment must be made within 30 days.","zh-TW":"合約規定付款必須在30天內完成。"},{"en":"Quality standards are clearly stipulated in the procurement guidelines.","zh-TW":"採購指南中明確規定了品質標準。"}]', '{"noun":"stipulation","adjective":"stipulated"}', NULL, 3, 2890, NULL),
(2891, 'stock', '/stɒk/', 'noun', '{"zh-TW":["存貨；股票","股票；庫存","儲備；進貨"],"en":["goods available for sale","shares in a company","shares in a company; goods kept for sale","to keep a supply of"]}', '{"root":{"text":"stock","meaning":"trunk/store (樹幹/儲存)"},"logic":"原指樹幹（根基），引申為儲存的貨物。"}', 'in stock / out of stock / stock market; stock market / in stock / out of stock / stock price', '[{"en":"Sorry, that item is out of stock.","zh-TW":"抱歉，那個商品缺貨了。"},{"en":"We need to restock the shelves.","zh-TW":"我們需要補貨上架。"},{"en":"The stock market rallied after the announcement.","zh-TW":"公告後股市反彈。"},{"en":"The item is currently out of stock.","zh-TW":"該商品目前缺貨。"}]', '{"verb":"stock","noun":"stockholder"}', NULL, 2, 2891, NULL),
(2892, 'stomach', '/ˈstʌmək/', 'verb, noun', '{"zh-TW":["【主要意義-名詞】胃；腹部","【次要意義-動詞】忍受；消化（情感上難以接受的事）"],"en":["[primary - noun] the organ that digests food; the abdomen","[secondary - verb] to tolerate or endure something unpleasant"]}', NULL, 'cannot stomach / stomach an insult / stomach the idea', '[{"en":"Many employees could not stomach the sudden pay cut announcement.","zh-TW":"許多員工無法接受突然宣布的薪資削減。"},{"en":"He found it hard to stomach the unfair criticism from upper management.","zh-TW":"他發現很難忍受來自高層管理的不公平批評。"},{"en":"She could not stomach the idea of working under such poor conditions.","zh-TW":"她無法忍受在如此惡劣的條件下工作的想法。"}]', '{"adjective":"stomach-turning"}', '動詞 stomach（尤其用於否定句 cannot stomach）= 「無法忍受/難以接受」，常見於 TOEIC 閱讀描述員工反應或職場情境的文章，與名詞「胃」完全不同。', 3, 2892, NULL),
(2893, 'stop', '/stɒp/', 'verb', '{"zh-TW":["停止"],"en":["to cease moving or doing"]}', NULL, 'stop by / non-stop', '[{"en":"Please stop by my office later.","zh-TW":"請待會過來我的辦公室一趟。"},{"en":"We worked non-stop to finish on time.","zh-TW":"我們不停地工作以準時完成。"}]', '{"verb":"stop","noun":"stop","noun2":"stoppage"}', NULL, 1, 2893, NULL),
(2894, 'stopover', '/ˈstɒpoʊvər/', 'noun', '{"zh-TW":["過境停留"],"en":["a break in a journey at an intermediate point"]}', NULL, 'overnight stopover / planned stopover', '[{"en":"They had a stopover in Singapore on the way to London.","zh-TW":"他們前往倫敦途中在新加坡過境停留。"},{"en":"A stopover can be a chance to explore a new city.","zh-TW":"過境停留可以是探索新城市的機會。"}]', NULL, NULL, 3, 2894, NULL),
(2895, 'storage', '/ˈstɔːrɪdʒ/', 'noun', '{"zh-TW":["儲存；儲存空間","儲存；倉儲"],"en":["the keeping of things for future use","the keeping of goods in a designated place"]}', NULL, 'cloud storage / storage space; data storage / storage capacity / cold storage', '[{"en":"I need more storage on my phone.","zh-TW":"我手機需要更多儲存空間。"},{"en":"Cloud storage is convenient.","zh-TW":"雲端儲存很方便。"},{"en":"Cloud storage has become essential for businesses.","zh-TW":"雲端儲存已成為企業的必需。"},{"en":"The warehouse has limited storage capacity.","zh-TW":"倉庫的儲存容量有限。"}]', '{"verb":"store","noun":"storage, store"}', NULL, 3, 2895, 462),
(2896, 'store', '/stɔːr/', 'noun', '{"zh-TW":["商店；儲存"],"en":["a retail shop","to keep for future use","a place where goods are sold"]}', '{"root":{"text":"store","meaning":"restore/keep (保存)"},"logic":"保存物品的地方，即「商店」或「倉庫」。"}', 'in store / store data; department store / store manager', '[{"en":"We have big changes in store.","zh-TW":"我們即將有重大變化。"},{"en":"Data is stored in the cloud.","zh-TW":"數據儲存在雲端。"},{"en":"The store opens at 9 a.m.","zh-TW":"商店早上九點開門。"},{"en":"Store the food in a cool dry place.","zh-TW":"將食物儲存在陰涼乾燥處。"}]', '{"noun":"store","verb":"store","noun2":"storage"}', NULL, 2, 2896, NULL),
(2897, 'storm', '/stɔːrm/', 'noun', '{"zh-TW":["暴風雨"],"en":["violent weather with strong winds and rain"]}', '{"root":{"text":"storm","meaning":"disturbance (擾動)"},"logic":"指大氣的劇烈擾動。"}', 'thunderstorm / storm warning / weather the storm', '[{"en":"A powerful storm is heading toward the coast.","zh-TW":"一場強烈暴風雨正朝海岸移動。"},{"en":"The company weathered the financial storm.","zh-TW":"公司挺過了金融風暴。"}]', '{"adjective":"stormy","verb":"storm"}', NULL, 2, 2897, NULL),
(2898, 'story', '/ˈstɔːri/', 'noun', '{"zh-TW":["故事；樓層"],"en":["a narrative","a level of a building"]}', NULL, 'success story / cover story', '[{"en":"Our company has a great success story.","zh-TW":"我們公司有一個精彩的成功故事。"},{"en":"The office building is ten stories tall.","zh-TW":"辦公大樓有十層樓高。"}]', '{"noun":"story","noun2":"storyline"}', NULL, 2, 2898, NULL),
(2899, 'straightforward', '/ˌstreɪtˈfɔːrwərd/', 'adjective', '{"zh-TW":["直截了當的；簡單的"],"en":["easy to understand; uncomplicated"]}', NULL, 'straightforward process / straightforward answer / fairly straightforward', '[{"en":"The application process is straightforward.","zh-TW":"申請流程很簡單。"},{"en":"He gave a straightforward answer to the question.","zh-TW":"他對問題給出了直截了當的回答。"}]', '{"adjective":"straightforward","adverb":"straightforwardly"}', NULL, 5, 2899, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2900, 'strategic', '/strəˈtiːdʒɪk/', 'adjective', '{"zh-TW":["戰略性的；策略性的"],"en":["relating to the planning and directing of overall business goals"]}', NULL, 'strategic decision / strategic priority / strategic partnership', '[{"en":"The acquisition was described as a strategic move into new markets.","zh-TW":"此次收購被描述為進入新市場的戰略舉措。"},{"en":"Strategic thinking sets leaders apart from operational managers.","zh-TW":"戰略思維將領導者與運營管理者區分開來。"}]', '{"adverb":"strategically","noun":"strategy"}', NULL, 3, 2900, NULL),
(2901, 'strategy', '/ˈstrætədʒi/', 'noun', '{"zh-TW":["策略","策略；戰略"],"en":["a plan of action to achieve a long-term goal","a plan designed to achieve a long-term goal"]}', '{"root":{"text":"strat","meaning":"army (軍隊)"},"suffix":{"text":"-egy","meaning":"leading (引領)"},"logic":"引領軍隊的計畫，即「策略」。"}', 'marketing strategy / business strategy / develop a strategy; business strategy / marketing strategy / develop a strategy', '[{"en":"We need a new strategy to increase sales.","zh-TW":"我們需要新策略來增加銷售。"},{"en":"The company developed a long-term growth strategy.","zh-TW":"公司制定了長期成長策略。"},{"en":"The company revised its marketing strategy.","zh-TW":"公司修改了行銷策略。"},{"en":"We need a clear strategy for expansion.","zh-TW":"我們需要明確的擴展策略。"}]', '{"adjective":"strategic","adverb":"strategically","noun2":"strategist","noun":"strategy, strategist"}', NULL, 3, 2901, 222),
(2902, 'streaming', '/ˈstriːmɪŋ/', 'noun', '{"zh-TW":["串流"],"en":["transmitting data continuously over the internet"]}', NULL, 'video streaming / streaming service', '[{"en":"Streaming has replaced traditional TV.","zh-TW":"串流取代了傳統電視。"},{"en":"Which streaming service do you subscribe to?","zh-TW":"你訂閱了哪個串流服務？"}]', '{"verb":"stream"}', NULL, 3, 2902, NULL),
(2903, 'streamline', '/ˈstriːmlaɪn/', 'verb', '{"zh-TW":["精簡；使流暢"],"en":["to make a process more efficient"]}', NULL, 'streamline operations / streamline processes / streamline workflow', '[{"en":"The company streamlined its production process.","zh-TW":"公司精簡了生產流程。"},{"en":"New technology helps streamline daily operations.","zh-TW":"新技術有助於精簡日常營運。"}]', '{"verb":"streamline","adjective":"streamlined"}', NULL, 4, 2903, 723),
(2904, 'streamlined', '/ˈstriːmlaɪnd/', 'adjective', '{"zh-TW":["精簡的；流線型的"],"en":["designed for efficiency; having smooth lines"]}', NULL, 'streamlined process / streamlined design / streamlined operations', '[{"en":"The new streamlined process saves two hours per day.","zh-TW":"新的精簡流程每天節省兩小時。"},{"en":"We implemented a streamlined approval system.","zh-TW":"我們實施了精簡的審批系統。"}]', '{"adjective":"streamlined","verb":"streamline"}', NULL, 4, 2904, NULL),
(2905, 'street', '/striːt/', 'noun', '{"zh-TW":["街道"],"en":["a public road in a city or town"]}', NULL, 'Wall Street / main street', '[{"en":"Wall Street reacted positively to the news.","zh-TW":"華爾街對這個消息反應正面。"},{"en":"The store is on the main street.","zh-TW":"商店在主要街道上。"}]', '{"noun":"street"}', NULL, 2, 2905, NULL),
(2906, 'strengthen', '/ˈstreŋθn/', 'verb', '{"zh-TW":["加強；增強"],"en":["to make or become stronger"]}', NULL, 'strengthen ties / strengthen the position / strengthen regulations', '[{"en":"The partnership will strengthen our market position.","zh-TW":"合作將加強我們的市場地位。"},{"en":"The government strengthened environmental regulations.","zh-TW":"政府加強了環境法規。"}]', '{"noun":"strength","verb":"strengthen","adjective":"strong"}', NULL, 4, 2906, NULL),
(2907, 'stress', '/stres/', 'noun, verb', '{"zh-TW":["壓力；緊張","強調"],"en":["mental or emotional pressure","to emphasize"]}', NULL, 'under stress / stress the importance / stress management', '[{"en":"She stressed the importance of meeting deadlines.","zh-TW":"她強調了遵守截止日期的重要性。"},{"en":"Many employees suffer from workplace stress.","zh-TW":"許多員工受到工作壓力的影響。"}]', '{"noun":"stress","verb":"stress","adjective":"stressful, stressed"}', NULL, 2, 2907, NULL),
(2908, 'strict', '/strɪkt/', 'adjective', '{"zh-TW":["嚴格的；嚴謹的"],"en":["demanding that rules are obeyed"]}', NULL, 'strict regulations / strict deadline / strict compliance', '[{"en":"The company has strict policies on data privacy.","zh-TW":"公司對資料隱私有嚴格的政策。"},{"en":"Strict compliance with safety standards is required.","zh-TW":"必須嚴格遵守安全標準。"}]', '{"adjective":"strict","adverb":"strictly","noun":"strictness"}', NULL, 2, 2908, NULL),
(2909, 'strike', '/straɪk/', 'noun, verb', '{"zh-TW":["【主要意義-動詞/名詞】打擊；罷工","【次要意義-動詞】給……留下印象；使覺得","【次要意義-動詞】達成（協議）；達到","【次要意義-名詞】（油/礦）新發現"],"en":["[primary] to hit something; a work stoppage","[secondary - verb] to make a strong impression on someone","[secondary - verb] to reach an agreement or achieve a balance","[secondary - noun] a sudden discovery of oil, gold, or similar resources"]}', NULL, 'strike a deal / strike a balance / strike me as / go on strike / lucky strike', '[{"en":"After weeks of negotiation, both sides struck a deal on the new contract.","zh-TW":"經過數週的談判，雙方就新合約達成了協議。"},{"en":"It strikes me as odd that no one was informed of the policy change.","zh-TW":"沒有人被告知政策變更，這讓我覺得很奇怪。"},{"en":"Workers went on strike to protest against the proposed pay freeze.","zh-TW":"工人舉行罷工，抗議擬議中的薪酬凍結。"}]', '{"noun":"striker","adjective":"striking"}', 'strike a deal/balance（達成協議/取得平衡）、strike me as（讓我覺得）是 TOEIC 商業談判文章的高頻表達，go on strike（舉行罷工）也是常考詞彙。', 2, 2909, NULL),
(2910, 'strive', '/straɪv/', 'verb', '{"zh-TW":["努力；奮鬥"],"en":["to make great efforts to achieve something"]}', NULL, 'strive for excellence / strive to achieve / strive to improve', '[{"en":"We strive for excellence in customer service.","zh-TW":"我們在客戶服務方面追求卓越。"},{"en":"The team strives to meet all deadlines.","zh-TW":"團隊努力在所有截止日前完成工作。"}]', '{"verb":"strive"}', NULL, 2, 2910, NULL),
(2911, 'strong', '/strɒŋ/', 'adjective', '{"zh-TW":["強壯的；強大的"],"en":["having great power","solid and difficult to break"]}', NULL, 'strong demand / strong leadership', '[{"en":"There is strong demand for this product.","zh-TW":"這個產品需求強勁。"},{"en":"Strong leadership guided the company through the crisis.","zh-TW":"強有力的領導帶領公司度過了危機。"}]', '{"adjective":"strong","adverb":"strongly","noun":"strength","verb":"strengthen"}', NULL, 2, 2911, NULL),
(2912, 'structure', '/ˈstrʌktʃər/', 'noun, verb', '{"zh-TW":["結構；組織","構建；組織"],"en":["the way something is organized","to arrange in a systematic way"]}', NULL, 'organizational structure / cost structure / well-structured', '[{"en":"The company restructured its organizational structure.","zh-TW":"公司重組了其組織結構。"},{"en":"The report is well-structured and easy to follow.","zh-TW":"報告結構完善，易於理解。"}]', '{"noun":"structure, restructuring","verb":"structure, restructure","adjective":"structural"}', NULL, 3, 2912, 223),
(2913, 'stubborn', '/ˈstʌbərn/', 'adjective', '{"zh-TW":["固執的"],"en":["refusing to change one''s mind"]}', '{"root":{"text":"stub","meaning":"stump (樹樁)"},"logic":"如同樹樁般不動搖的，即「固執的」。"}', 'stubborn refusal / stubborn as a mule', '[{"en":"He is too stubborn to ask for help.","zh-TW":"他太固執不肯求助。"},{"en":"Her stubborn refusal caused problems.","zh-TW":"她固執的拒絕造成了問題。"}]', '{"noun":"stubbornness","adverb":"stubbornly"}', NULL, 3, 2913, NULL),
(2914, 'student', '/ˈstjuːdənt/', 'noun', '{"zh-TW":["學生"],"en":["a person who is studying"]}', NULL, 'student loan / exchange student', '[{"en":"Student loans are a heavy burden.","zh-TW":"學生貸款是沉重的負擔。"},{"en":"We hire exchange students as interns.","zh-TW":"我們聘請交換學生當實習生。"}]', '{"noun":"student","noun2":"study","verb":"study"}', NULL, 3, 2914, NULL),
(2915, 'studio', '/ˈstjuːdioʊ/', 'noun', '{"zh-TW":["工作室；錄音室"],"en":["a room where an artist or musician works"]}', '{"root":{"text":"studi","meaning":"study/devote (研究/投入)"},"suffix":{"text":"-o","meaning":"place (場所)"},"logic":"投入研究創作的場所，即「工作室」。"}', 'art studio / recording studio / studio apartment', '[{"en":"The photographer works in her studio.","zh-TW":"攝影師在她的工作室工作。"},{"en":"The band recorded the album in a professional studio.","zh-TW":"樂團在專業錄音室錄製了這張專輯。"}]', NULL, NULL, 2, 2915, NULL),
(2916, 'study', '/ˈstʌdi/', 'verb', '{"zh-TW":["學習；研究"],"en":["to learn about a subject","to examine carefully"]}', NULL, 'case study / feasibility study', '[{"en":"We conducted a feasibility study.","zh-TW":"我們進行了可行性研究。"},{"en":"This case study shows best practices.","zh-TW":"這個案例研究展示了最佳實踐。"}]', '{"verb":"study","noun":"study","noun2":"student"}', NULL, 2, 2916, NULL),
(2917, 'style', 'staɪl', 'noun', '{"zh-TW":["風格；方式","樣式"],"en":["a way of doing something","a particular design"]}', NULL, 'work style/management style', '[{"en":"Her management style is collaborative.","zh-TW":"她的管理風格是協作式的。"}]', '{"verb":"style","adjective":"stylish","adverb":"stylishly"}', NULL, 2, 2917, NULL),
(2918, 'subagent', '/ˈsʌbeɪdʒənt/', 'noun', '{"zh-TW":["次代理；子代理人"],"en":["an agent authorized by another agent to perform certain duties"]}', NULL, 'appoint a subagent / subagent agreement', '[{"en":"The broker appointed a local subagent in each city.","zh-TW":"經紀人在每個城市任命了一名本地次代理。"},{"en":"The subagent is authorized to sign documents on behalf of the main agent.","zh-TW":"次代理有權代表主要代理人簽署文件。"}]', NULL, NULL, 3, 2918, NULL),
(2919, 'subcontract', '/ˌsʌbkənˈtrækt/', 'verb, noun', '{"zh-TW":["分包；轉包","分包合約"],"en":["to hire another company to do part of the work"]}', NULL, 'subcontract work / subcontract to / subcontractor', '[{"en":"The firm subcontracted the IT work to a specialist.","zh-TW":"公司將IT工作分包給專業人員。"},{"en":"We use subcontractors for maintenance services.","zh-TW":"我們使用分包商提供維護服務。"}]', '{"noun":"subcontract, subcontractor","verb":"subcontract"}', NULL, 4, 2919, NULL),
(2920, 'subcontractor', '/ˌsʌbkənˈtræktər/', 'noun', '{"zh-TW":["分包商；次承包商"],"en":["a company hired by the main contractor to complete specific work"]}', NULL, 'hire a subcontractor / subcontractor agreement', '[{"en":"The builder hired a subcontractor to install the electrical systems.","zh-TW":"建築商聘請了分包商安裝電力系統。"},{"en":"Subcontractor performance affects the main project timeline.","zh-TW":"分包商的表現影響著主項目的時間表。"}]', '{"verb":"subcontract","adjective":"subcontracted"}', NULL, 5, 2920, NULL),
(2921, 'subject', '/ˈsʌbdʒɪkt/', 'noun, adjective, verb', '{"zh-TW":["主題；科目","受...支配的","使遭受"],"en":["a topic; a branch of study","dependent on","to cause to experience"]}', NULL, 'subject to / on the subject of / subject matter', '[{"en":"The plan is subject to board approval.","zh-TW":"該計畫需經董事會批准。"},{"en":"Let''s not change the subject.","zh-TW":"我們不要改變話題。"}]', '{"noun":"subject","verb":"subject","adjective":"subject, subjective"}', NULL, 3, 2921, 463),
(2922, 'sublease', '/ˈsʌbliːs/', 'noun', '{"zh-TW":["轉租；分租"],"en":["renting property that you have leased from another party"]}', NULL, 'sublease agreement / enter a sublease / sublease the office', '[{"en":"The company subleased part of its office space to a startup.","zh-TW":"公司將部分辦公空間轉租給一家新創公司。"},{"en":"The sublease required approval from the original landlord.","zh-TW":"轉租需要原房東的批准。"}]', '{"verb":"sublease","noun":"sublessee"}', NULL, 3, 2922, NULL),
(2923, 'submission', 'səbˈmɪʃən', 'noun', '{"zh-TW":["提交；呈遞","服從"],"en":["the act of presenting formally","a document submitted"]}', NULL, 'on-time submission/final submission', '[{"en":"Please ensure on-time submission.","zh-TW":"請確保按時提交。"}]', '{"verb":"submit","adjective":"submitted"}', NULL, 4, 2923, 624),
(2924, 'submit', '/səbˈmɪt/', 'verb', '{"zh-TW":["提交；呈交","服從"],"en":["to present for consideration","to yield to authority"]}', '{"prefix":{"text":"sub-","meaning":"在...之下"},"root":{"text":"mit","meaning":"send (發送)"}}', 'submit a report / submit an application / submit a proposal', '[{"en":"Please submit your application by Friday.","zh-TW":"請在週五前提交您的申請。"},{"en":"All expenses must be submitted for approval.","zh-TW":"所有費用都必須提交審批。"}]', '{"noun":"submission","verb":"submit"}', NULL, 2, 2924, 62),
(2925, 'subordinate', '/səˈbɔːrdɪnət/', 'noun, adjective', '{"zh-TW":["下屬；部屬","次要的；從屬的"],"en":["a person under the authority of another","lower in rank"]}', NULL, 'subordinate to / direct subordinate', '[{"en":"Managers should support their subordinates.","zh-TW":"經理應該支持他們的下屬。"},{"en":"Personal interests are subordinate to company goals.","zh-TW":"個人利益從屬於公司目標。"}]', '{"noun":"subordinate, subordination","adjective":"subordinate","verb":"subordinate"}', NULL, 4, 2925, 937),
(2926, 'subscribe', '/səbˈskraɪb/', 'verb', '{"zh-TW":["訂閱；認購","同意"],"en":["to pay regularly for a service","to agree with an idea"]}', NULL, 'subscribe to / subscription service / subscribe to a newsletter', '[{"en":"Over 10,000 users subscribe to our newsletter.","zh-TW":"超過一萬名用戶訂閱我們的電子報。"},{"en":"I don''t subscribe to that theory.","zh-TW":"我不認同那個理論。"}]', '{"noun":"subscription, subscriber","verb":"subscribe"}', NULL, 3, 2926, NULL),
(2927, 'subscription', '/səbˈskrɪpʃən/', 'noun', '{"zh-TW":["訂閱；訂閱制"],"en":["a model where customers pay regularly for ongoing access to a product"]}', NULL, 'subscription model / subscription fee / annual subscription / cancel subscription', '[{"en":"The company switched to a subscription model for stable recurring revenue.","zh-TW":"公司轉向訂閱模式以獲得穩定的經常性收入。"},{"en":"Monthly subscriptions increased by 40% after the price reduction.","zh-TW":"降價後，月度訂閱數量增加了40%。"}]', '{"verb":"subscribe","noun":"subscriber"}', NULL, 4, 2927, NULL),
(2928, 'subsequent', '/ˈsʌbsɪkwənt/', 'adjective', '{"zh-TW":["隨後的；後續的"],"en":["coming after something in time"]}', NULL, 'subsequent to / subsequent events / in subsequent years', '[{"en":"Subsequent meetings will address remaining issues.","zh-TW":"後續會議將處理剩餘問題。"},{"en":"Sales improved in subsequent quarters.","zh-TW":"銷售額在接下來的幾季有所改善。"}]', '{"adjective":"subsequent","adverb":"subsequently"}', NULL, 4, 2928, NULL),
(2929, 'subsidiary', '/səbˈsɪdieri/', 'noun, adjective', '{"zh-TW":["子公司","附屬的；次要的"],"en":["a company controlled by another company","less important"]}', NULL, 'wholly-owned subsidiary / subsidiary company', '[{"en":"The company has subsidiaries in 20 countries.","zh-TW":"該公司在20個國家設有子公司。"},{"en":"This is a wholly-owned subsidiary of the group.","zh-TW":"這是集團的全資子公司。"}]', '{"noun":"subsidiary"}', NULL, 4, 2929, NULL),
(2930, 'subsidy', '/ˈsʌbsɪdi/', 'noun', '{"zh-TW":["補貼；補助金"],"en":["money granted by the government to assist an industry"]}', NULL, 'government subsidy / subsidy program', '[{"en":"The government provides subsidies for electric vehicle purchases.","zh-TW":"政府為購買電動車提供補貼。"},{"en":"Subsidies for renewable energy have driven its rapid expansion.","zh-TW":"對可再生能源的補貼推動了其快速擴展。"}]', '{"verb":"subsidize","adjective":"subsidized"}', NULL, 3, 2930, NULL),
(2931, 'substance', '/ˈsʌbstəns/', 'noun', '{"zh-TW":["物質；實質","要旨"],"en":["a type of matter","the real content or meaning"]}', NULL, 'chemical substance / in substance / substance abuse', '[{"en":"The report lacks substance.","zh-TW":"這份報告缺乏實質內容。"},{"en":"Hazardous substances must be handled carefully.","zh-TW":"危險物質必須小心處理。"}]', '{"noun":"substance","adjective":"substantial, substantive"}', NULL, 3, 2931, NULL),
(2932, 'substandard', '/ˌsʌbˈstændərd/', 'adjective', '{"zh-TW":["低於標準的；不合格的"],"en":["below the required or expected quality"]}', NULL, 'substandard goods / substandard work / substandard quality', '[{"en":"The supplier delivered substandard components that failed quality checks.","zh-TW":"供應商交付了未能通過品質檢查的不合格零件。"},{"en":"Substandard work will not be accepted by the client.","zh-TW":"客戶不會接受不合格的工作。"}]', '{"adverb":"substandard"}', NULL, 4, 2932, NULL),
(2933, 'substantial', '/səbˈstænʃl/', 'adjective', '{"zh-TW":["大量的；可觀的","實質的"],"en":["of considerable importance or size"]}', NULL, 'substantial amount / substantial improvement / substantial evidence', '[{"en":"We made a substantial investment in technology.","zh-TW":"我們在技術方面進行了大量投資。"},{"en":"There has been substantial improvement in quality.","zh-TW":"品質有了顯著的改善。"}]', '{"noun":"substance","adjective":"substantial","adverb":"substantially"}', NULL, 4, 2933, NULL),
(2934, 'substitute', '/ˈsʌbstɪtuːt/', 'noun, verb', '{"zh-TW":["替代品；代替者","替代；取代"],"en":["a person or thing acting in place of another","to use instead of"]}', NULL, 'substitute for / substitute teacher / no substitute for', '[{"en":"There is no substitute for hard work.","zh-TW":"勤奮是無可替代的。"},{"en":"You can substitute olive oil for butter.","zh-TW":"你可以用橄欖油代替奶油。"}]', '{"noun":"substitute, substitution","verb":"substitute"}', NULL, 4, 2934, NULL),
(2935, 'subtle', '/ˈsʌtl/', 'adjective', '{"zh-TW":["微妙的；細微的"],"en":["not immediately obvious; delicate"]}', NULL, 'subtle difference / subtle change / subtle hint', '[{"en":"There is a subtle difference between the two products.","zh-TW":"這兩款產品之間有微妙的差異。"},{"en":"She made a subtle hint about the promotion.","zh-TW":"她暗示了關於升遷的事。"}]', '{"noun":"subtlety","adjective":"subtle","adverb":"subtly"}', NULL, 2, 2935, NULL),
(2936, 'succeed', '/səkˈsiːd/', 'verb', '{"zh-TW":["成功；繼任"],"en":["to achieve a goal; to come after"]}', NULL, 'succeed in / succeed as / succeed someone', '[{"en":"The company succeeded in entering the Asian market.","zh-TW":"公司成功進入了亞洲市場。"},{"en":"She succeeded him as CEO.","zh-TW":"她接替他擔任執行長。"}]', '{"noun":"success, succession, successor","verb":"succeed","adjective":"successful, successive"}', NULL, 3, 2936, NULL),
(2937, 'success', 'səkˈsɛs', 'noun', '{"zh-TW":["成功；成就","好結果"],"en":["the achievement of a goal","a favorable outcome"]}', NULL, 'business success/measure of success', '[{"en":"Success depends on teamwork.","zh-TW":"成功取決於團隊合作。"}]', '{"verb":"succeed","adjective":"successful","adverb":"successfully"}', NULL, 3, 2937, NULL),
(2938, 'successful', 'səkˈsɛsfəl', 'adjective', '{"zh-TW":["成功的；有成就的","出色的"],"en":["having achieved a desired goal","prosperous"]}', NULL, 'successful project/successful launch', '[{"en":"The product launch was very successful.","zh-TW":"產品發布非常成功。"}]', '{"noun":"success","adverb":"successfully"}', NULL, 4, 2938, 224),
(2939, 'succession', '/səkˈseʃən/', 'noun', '{"zh-TW":["接替；繼承"],"en":["the process of one person taking over another''s role or position"]}', NULL, 'succession plan / succession of management / leadership succession', '[{"en":"Smooth succession is critical to maintaining business continuity.","zh-TW":"順暢的繼任對維持業務連續性至關重要。"},{"en":"The board developed a succession strategy for the retiring CFO.","zh-TW":"董事會為即將退休的財務長制定了繼任策略。"}]', '{"verb":"succeed","noun":"successor"}', NULL, 4, 2939, 938),
(2940, 'sufficient', '/səˈfɪʃnt/', 'adjective', '{"zh-TW":["足夠的","足夠的；充分的"],"en":["enough to meet the needs"]}', '{"prefix":{"text":"suf-","meaning":"under/up (從下)"},"root":{"text":"fic","meaning":"make/do (做)"},"suffix":{"text":"-ient","meaning":"being (…的)"},"logic":"做到位的，即「足夠的」。"}', 'sufficient evidence / sufficient time / self-sufficient; sufficient funds / sufficient evidence / self-sufficient', '[{"en":"Do we have sufficient time to finish?","zh-TW":"我們有足夠的時間完成嗎？"},{"en":"The evidence is not sufficient to prove guilt.","zh-TW":"證據不足以證明有罪。"},{"en":"We have sufficient funds to complete the project.","zh-TW":"我們有足夠的資金完成這個專案。"},{"en":"The evidence is not sufficient to prove the claim.","zh-TW":"證據不足以證明該主張。"}]', '{"noun":"sufficiency","adverb":"sufficiently","adjective":"sufficient, insufficient"}', NULL, 4, 2940, NULL),
(2941, 'suggest', '/səˈdʒest/', 'verb', '{"zh-TW":["建議；暗示"],"en":["to put forward an idea; to indicate"]}', NULL, 'suggest that / strongly suggest / suggest an alternative', '[{"en":"I suggest we postpone the meeting.","zh-TW":"我建議我們延後會議。"},{"en":"The data suggests a positive trend.","zh-TW":"數據暗示了一個正面的趨勢。"}]', '{"noun":"suggestion","verb":"suggest","adjective":"suggestive"}', NULL, 3, 2941, NULL),
(2942, 'suit', '/suːt/', 'noun, verb', '{"zh-TW":["【主要意義-名詞】西裝；套裝","【次要意義-動詞】適合；對……合適","【次要意義-名詞】訴訟；法律行動","【次要意義-名詞】（撲克牌）花色"],"en":["[primary - noun] a set of matching clothes","[secondary - verb] to be convenient or appropriate for someone","[secondary - noun] a legal case or proceeding","[secondary - noun] one of the four sets of cards in a deck"]}', NULL, 'suit someone / file a suit / follow suit / a lawsuit / strong suit', '[{"en":"The new office hours suit most employees very well.","zh-TW":"新的辦公時間非常適合大多數員工。"},{"en":"The company filed a suit against its former partner for breach of contract.","zh-TW":"公司就違約問題對前合作夥伴提起了訴訟。"},{"en":"When the market leader lowered prices, competitors followed suit.","zh-TW":"當市場領導者降價時，競爭者也紛紛效仿。"}]', '{"adjective":"suitable, unsuitable","noun":"suitability"}', '動詞 suit = 「適合」，名詞 suit = 「訴訟」（lawsuit），片語 follow suit = 「效仿/跟進」，TOEIC 法律和商業文章的高頻詞彙。', 1, 2942, NULL),
(2943, 'suitable', 'ˈsuːtəbəl', 'adjective', '{"zh-TW":["合適的；適宜的","相稱的"],"en":["right for a particular purpose","appropriate"]}', NULL, 'suitable candidate/suitable time', '[{"en":"Is Monday a suitable time for the meeting?","zh-TW":"週一是開會的合適時間嗎？"}]', '{"noun":"suitability","adverb":"suitably"}', NULL, 3, 2943, NULL),
(2944, 'suite', '/swiːt/', 'noun', '{"zh-TW":["套房"],"en":["a set of connected rooms in a hotel"]}', NULL, 'luxury suite / book a suite', '[{"en":"They booked a suite for their honeymoon.","zh-TW":"他們為蜜月預訂了套房。"},{"en":"The suite includes a living room and a bedroom.","zh-TW":"套房包含客廳和臥室。"}]', NULL, NULL, 2, 2944, NULL),
(2945, 'summarize', '/ˈsʌməraɪz/', 'verb', '{"zh-TW":["總結；概述"],"en":["to give a brief statement of the main points"]}', NULL, 'summarize the findings / to summarize / briefly summarize', '[{"en":"Please summarize the key findings of the report.","zh-TW":"請總結報告的主要發現。"},{"en":"To summarize, we need to reduce costs by 15%.","zh-TW":"總結來說，我們需要降低15%的成本。"}]', '{"noun":"summary","verb":"summarize"}', NULL, 3, 2945, NULL),
(2946, 'summary', 'ˈsʌməri', 'noun', '{"zh-TW":["摘要；總結","概要"],"en":["a brief statement of main points","an overview"]}', NULL, 'executive summary/provide a summary', '[{"en":"Please provide a summary of the report.","zh-TW":"請提供報告的摘要。"}]', '{"verb":"summarize","adjective":"summary"}', NULL, 3, 2946, 464),
(2947, 'summit', '/ˈsʌmɪt/', 'noun', '{"zh-TW":["高峰會；峰會","頂點"],"en":["a meeting between heads of government","the highest point"]}', NULL, 'economic summit / summit meeting / reach the summit', '[{"en":"Leaders gathered for the G20 summit.","zh-TW":"領袖們齊聚G20高峰會。"},{"en":"The summit addressed climate change issues.","zh-TW":"峰會討論了氣候變遷議題。"}]', '{"noun":"summit"}', NULL, 2, 2947, NULL),
(2948, 'supervise', '/ˈsuːpərvaɪz/', 'verb', '{"zh-TW":["監督；管理"],"en":["to oversee the work of others"]}', NULL, 'supervise employees / supervise a project / closely supervised', '[{"en":"She supervises a team of 15 engineers.","zh-TW":"她管理一個15人的工程師團隊。"},{"en":"The construction work is closely supervised.","zh-TW":"施工工程受到密切監督。"}]', '{"noun":"supervision, supervisor","verb":"supervise","adjective":"supervisory"}', NULL, 3, 2948, NULL),
(2949, 'supervisor', '/ˈsuːpərvaɪzər/', 'noun', '{"zh-TW":["主管；監督者"],"en":["a person who oversees the work of other employees"]}', NULL, 'direct supervisor / report to a supervisor / supervisory role', '[{"en":"He reported any issues directly to his supervisor.","zh-TW":"他直接向主管報告任何問題。"},{"en":"The supervisor provided daily guidance to the team.","zh-TW":"主管每天向團隊提供指導。"}]', '{"plural":"supervisors","verb":"supervise","adjective":"supervisory"}', NULL, 4, 2949, NULL);